    } else {
      alert('保存失败');
    }
  } catch (error) {
    console.error('保存错误:', error);
    alert('保存失败');
  }
}

// 关闭对话框
function closeDialog() {
  document.getElementById('dialog').classList.remove('show');
  resetForm();
}

// 重置表单
function resetForm() {
  document.getElementById('goodsForm').reset();
  document.getElementById('formGoodsType').value = '织纱';
